// Renders the real CANDOR-07 briefing (fetched fresh, one hop upstream)
// into read-only HTML for the review form's second page. All values are
// substituted here (not left as {{ }} placeholders) so the form field's
// content is a plain, already-resolved string.
function escapeHtml(str) {
  return String(str === undefined || str === null ? '' : str)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

const item = $input.item.json;
const candidateId = item.candidate_id;
const briefingText = item.briefing_text;

if (!candidateId || !briefingText) {
  throw new Error(
    'BuildReviewPageHtml: incomplete briefing record received from CANDOR-07 (missing candidate_id or briefing_text) - refusing to render a partial review page.'
  );
}

const briefingParagraphs = String(briefingText)
  .split(/\n\s*\n/)
  .map((p) => '<p>' + escapeHtml(p).replace(/\n/g, '<br>') + '</p>')
  .join('\n');

const qaStatus = item.qa_passed === true ? 'passed' : (item.qa_passed === false ? 'FLAGGED - see CANDOR-07 build log' : 'not run');

const reviewHtml = [
  '<h3>Candidate ' + escapeHtml(candidateId) + ' - ' + escapeHtml(item.job_title || item.job_id || '') + '</h3>',
  '<p><strong>Match Score:</strong> ' + escapeHtml(item.match_score) + ' &nbsp; <strong>Evidence Confidence:</strong> ' + escapeHtml(item.evidence_confidence) + '</p>',
  '<p><strong>Interpretation label:</strong> ' + escapeHtml(item.interpretation) + (item.low_evidence_confidence_flag ? '<br><em>Low evidence confidence flag: TRUE</em>' : '') + '</p>',
  '<hr>',
  briefingParagraphs,
  '<hr>',
  '<p><small>Briefing generated ' + escapeHtml(item.generated_at) + ' from audit record dated ' + escapeHtml(item.source_audit_record_audited_at) + '. QA self-check: ' + qaStatus + '.</small></p>',
  '<p><small>This is a diagnostic aid only. Nothing on this page executes any action - your decision below is recorded, not carried out automatically.</small></p>'
].join('\n');

return [{
  json: {
    ...item,
    review_html: reviewHtml
  }
}];

// Persists exactly one new, append-only decision record. Never overwrites
// candor08-records.jsonl or any prior decision - a changed mind is a new
// record, same discipline CANDOR-08 itself already follows.
const briefing = $('CallCANDOR07ForBriefing').first().json;
const decisionInput = $input.item.json;

const candidateId = briefing.candidate_id;
const jobId = briefing.job_id;

if (!candidateId || !jobId) {
  throw new Error('BuildDecisionRecord: missing candidate_id or job_id from the CANDOR-07 briefing record - refusing to persist an unlinked decision.');
}

const ALLOWED_DECISIONS = ['ADVANCE', 'REJECT', 'HOLD_MORE_INFO_NEEDED'];
const decision = decisionInput.decision;
if (!ALLOWED_DECISIONS.includes(decision)) {
  throw new Error('BuildDecisionRecord: decision "' + decision + '" is not one of the allowed values (' + ALLOWED_DECISIONS.join(', ') + ').');
}

const deciderName = String(decisionInput.decider_name || '').trim();
const deciderEmail = String(decisionInput.decider_email || '').trim();
if (!deciderName || !deciderEmail) {
  throw new Error('BuildDecisionRecord: decider_name and decider_email are both required - refusing to record an unattributed decision.');
}

const decisionRecord = {
  candidate_id: candidateId,
  job_id: jobId,
  job_title: briefing.job_title || null,
  decision: decision,
  decider_name: deciderName,
  decider_email: deciderEmail,
  decision_notes: decisionInput.decision_notes || null,
  source_audit_record_audited_at: briefing.source_audit_record_audited_at || null,
  match_score_at_decision: briefing.match_score,
  evidence_confidence_at_decision: briefing.evidence_confidence,
  interpretation_at_decision: briefing.interpretation,
  briefing_text_reviewed: briefing.briefing_text,
  briefing_generated_at: briefing.generated_at || null,
  decision_schema_version: 'CANDOR-10 decision-record v0.1',
  decided_at: new Date().toISOString(),
  decision_disclaimer: "This record documents a human reviewer's stated decision on a CANDOR-07 briefing. CANDOR itself never executes reject, advance, contact, or share actions - any action based on this decision is carried out separately, by the human reviewer, outside of CANDOR (Master Instructions section 13)."
};

return [{
  json: {
    ...decisionRecord,
    decision_line: JSON.stringify(decisionRecord) + '\n'
  }
}];

